import React from "react";
import "./App.css";

function App() {
  return (
    <div>
      <header>
        <h1>Library Management System</h1>
      </header>

      <nav>
        <a href="#">Home</a>
        <a href="#">Books</a>
        <a href="#">Members</a>
        <a href="#">Login</a>
      </nav>

      <section>
        <h2>Welcome to Library Management System</h2>

        <p>Manage books, members, issue and return books easily.</p>

        <button>View Books</button>
      </section>

      <footer>
        <p>© 2026 Library Management System</p>
      </footer>
    </div>
  );
}

export default App;
